// Hammered Copper - beaten metal with hammer dents, ridges and a touch of
// verdigris. Parametric (u,v), static.
//
// Each Voronoi cell is a shallow dent (a paraboloid around the cell point);
// the dents meet in sharp ridges. The fake normal reflects a simple sky /
// ground environment plus a highlight, which reads as polished metal even
// before the scene lighting. Verdigris collects along the ridges.
// SEAM-FREE: whole numbers of dents per turn, wrapped cell indices. Twisted
// gluing (Klein bottle, Moebius band): set MIRROR_V to 1.0.
// Dock colors: u_col1 = bright copper, u_col2 = dark copper / shadow.

const float CELLS_U  = 26.0;   // dents around u (whole number)     [8 .. 60]
const float CELLS_V  = 20.0;   // dents around v (whole number)     [6 .. 60]
const float DENT     = 0.55;   // depth of the dents                [0 .. 1.5]
const float SHINE    = 0.8;    // strength of the highlight         [0 .. 1.5]
const float PATINA   = 0.35;   // verdigris on the ridges           [0 .. 1]
const float SCRATCH  = 0.08;   // fine brushing marks               [0 .. 0.4]
const float MIRROR_U = 0.0;    // 1 = fold u
const float MIRROR_V = 0.0;    // 1 = fold v (Klein bottle, Moebius band)

// ---- seam-free toolkit: every grid has a whole number of cells per turn and
// ---- every cell index is wrapped, so the pattern repeats exactly at u, v = 0/1
vec2 seamFold(vec2 q) {
    vec2 tri = 0.5 - abs(fract(q) - 0.5);   // 0 -> 0.5 -> 0: equal at both ends
    return mix(q, tri, vec2(MIRROR_U, MIRROR_V));
}

// random value of cell c, wrapped into the period n (negative indices too):
// the same cell one turn away gets the same value.
// NB: helper functions here return float/vecN only -- the per-mesh renamer of
// the engine recognizes those return types, not ivec2.
float cellHash(ivec2 c, ivec2 n, int salt) {
    ivec2 w = ivec2(mod(vec2(c), vec2(n)));
    uint h = uint(w.x) * 0x8da6b343u + uint(w.y) * 0xd8163841u + uint(salt) * 0xcb1ab31fu;
    h ^= h >> 15; h *= 0x2c1b3c6du;
    h ^= h >> 12; h *= 0x297a2d39u;
    h ^= h >> 15;
    return float(h >> 8) * (1.0 / 16777216.0);
}

vec2 cellHash2(ivec2 c, ivec2 n, int salt) {
    return vec2(cellHash(c, n, salt), cellHash(c, n, salt + 101));
}

// value noise with a period of n cells; uv in turns (0..1 = one turn)
float pnoise(vec2 uv, ivec2 n, int salt) {
    vec2 p = uv * vec2(n);
    ivec2 i = ivec2(floor(p));
    vec2 f = fract(p);
    vec2 w = f * f * (3.0 - 2.0 * f);
    float a = cellHash(i, n, salt);
    float b = cellHash(i + ivec2(1, 0), n, salt);
    float c = cellHash(i + ivec2(0, 1), n, salt);
    float d = cellHash(i + ivec2(1, 1), n, salt);
    return mix(mix(a, b, w.x), mix(c, d, w.x), w.y);
}

// fractal sum: each octave doubles the cells, so it stays periodic
float pfbm(vec2 uv, ivec2 n, int octaves, int salt) {
    float sum = 0.0;
    float amp = 0.5;
    float norm = 0.0;
    for (int o = 0; o < 6; o++) {
        if (o >= octaves) break;
        sum += amp * pnoise(uv, n, salt + 17 * o);
        norm += amp;
        amp *= 0.5;
        n *= 2;
    }
    return sum / norm;
}

// Voronoi on a grid of n cells per turn (p in cells). Returns
//   x = distance to the nearest point, y = distance to the nearest border,
//   z = random id of the nearest cell.
// rel = p minus the nearest point; edgeDir = unit vector toward the nearest
// border (the downhill direction of anything that rises from the borders).
vec3 pvoronoi(vec2 p, ivec2 n, float jitter, int salt, out vec2 rel, out vec2 edgeDir) {
    ivec2 ip = ivec2(floor(p));
    vec2 fp = fract(p);
    float best = 1.0e9;
    ivec2 bestCell = ivec2(0);
    vec2 bestPt = vec2(0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        ivec2 g = ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 dv = pt - fp;
        float dd = dot(dv, dv);
        if (dd < best) { best = dd; bestCell = g; bestPt = pt; }
    }
    float border = 1.0e9;
    edgeDir = vec2(1.0, 0.0);
    for (int j = -1; j <= 1; j++)
    for (int i = -1; i <= 1; i++) {
        if (i == 0 && j == 0) continue;
        ivec2 g = bestCell + ivec2(i, j);
        vec2 pt = vec2(g) + 0.5 + jitter * (cellHash2(ip + g, n, salt) - 0.5);
        vec2 ab = pt - bestPt;
        float lab = length(ab);
        if (lab < 1.0e-5) continue;
        vec2 dir = ab / lab;
        float dist = dot(0.5 * (bestPt + pt) - fp, dir);
        if (dist < border) { border = dist; edgeDir = dir; }
    }
    rel = fp - bestPt;
    return vec3(sqrt(best), border, cellHash(ip + bestCell, n, salt + 7));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = seamFold(fragCoord / iResolution.xy);
    ivec2 n = ivec2(int(CELLS_U), int(CELLS_V));
    vec2 p = uv * vec2(n);

    vec2 rel, edgeDir;
    vec3 vor = pvoronoi(p, n, 0.85, 9, rel, edgeDir);

    // dent = paraboloid rising toward the ridges: gradient = 2 * DENT * rel.
    // Each dent has its own depth, so the ridges are uneven like real work.
    float depth = DENT * (0.7 + 0.6 * vor.z);
    // the ridge itself is rounded off by the hammer: slope fades on it
    vec2 grad = 2.0 * depth * rel * smoothstep(0.0, 0.06, vor.y);
    // brushing marks: a fine streak noise along u tilts the normal a little
    float streak = pnoise(uv, ivec2(n.x * 2, n.y * 60), 31) - 0.5;
    grad.y += SCRATCH * streak;
    vec3 N = normalize(vec3(-grad, 1.0));

    // reflection of the viewer (looking down the normal of the sheet)
    vec3 R = reflect(vec3(0.0, 0.0, -1.0), N);
    float env = smoothstep(-0.55, 0.55, dot(R.xy, vec2(-0.35, 0.94)));
    vec3 Lh = normalize(vec3(-0.45, 0.6, 0.65));
    float spark = pow(max(dot(R, Lh), 0.0), 40.0);

    vec3 col = mix(u_col2, u_col1, 0.2 + 0.8 * env) * (0.92 + 0.16 * vor.z);
    col += SHINE * spark * mix(u_col1, vec3(1.0), 0.55);

    // dark hairline on the crest of each ridge
    float ridge = 1.0 - smoothstep(0.0, 0.05, vor.y);
    col *= 1.0 - 0.25 * ridge;

    // verdigris: patches of green-blue that settle along the ridges
    float spots = smoothstep(0.45, 0.75, pfbm(uv, n / 2 + 1, 4, 63));
    float settle = 1.0 - smoothstep(0.0, 0.22, vor.y);
    vec3 verdigris = vec3(0.32, 0.62, 0.52);
    col = mix(col, verdigris * (0.7 + 0.3 * env), PATINA * spots * settle);

    fragColor = vec4(clamp(col, 0.0, 1.0), 1.0);
}
